package local.z6panel;

import android.content.*;
import android.net.Uri;
import android.os.*;
import org.json.*;
import java.io.*;
import java.lang.ref.WeakReference;
import java.util.*;
import java.util.concurrent.*;

/** User-requested imports survive Activity recreation. Results contain no image content. */
final class WallpaperImports {
 static final class Item {final Uri uri;final String name;final boolean release;Item(Uri u,String n){this(u,n,false);}Item(Uri u,String n,boolean r){uri=u;name=n;release=r;}}
 static final class Result {final String token;final List<String> ids,errors;final int total,processed;final boolean running;Result(String t,List<String> i,List<String> e,int all,int done,boolean active){token=t;ids=i;errors=e;total=all;processed=done;running=active;}String summary(){return running?"Importando "+processed+" / "+total+"…":"Importadas: "+ids.size()+" · Errores: "+errors.size();}}
 interface Listener {void changed(Result result);}
 private static final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,15,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),r->new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);r.run();},"Z6-image-import"));
 private static final Object STATE_LOCK=new Object();private static volatile boolean busy;private static WeakReference<Listener> listener=new WeakReference<>(null);
 static void attach(Context c,Listener l){listener=new WeakReference<>(l);Result result=read(c);if(result!=null)l.changed(result);}
 static void detach(Listener l){if(listener.get()==l)listener.clear();}
 private static File state(Context c){return new File(c.getFilesDir(),"last-image-import.json");}
 private static void save(Context c,String token,List<String> ids,List<String> errors,List<Item> items,int done,boolean running)throws Exception{synchronized(STATE_LOCK){JSONArray valid=new JSONArray();for(String id:ids)if(new File(new File(c.getFilesDir(),"wallpapers"),id+".jpg").isFile())valid.put(id);JSONArray leases=new JSONArray();if(running)for(Item item:items)if(item.release)leases.put(item.uri.toString());WallpaperStore.writeJson(state(c),new JSONObject().put("token",token).put("ids",valid).put("errors",new JSONArray(errors)).put("total",items.size()).put("processed",done).put("running",running).put("leases",leases).toString());}}
 static void forget(Context c,Set<String> removed){synchronized(STATE_LOCK){if(removed.isEmpty())return;try{File file=state(c);try(FileInputStream in=new android.util.AtomicFile(file).openRead()){JSONObject j=new JSONObject(new String(WallpaperStore.readLimited(in,131072),"UTF-8"));JSONArray old=j.optJSONArray("ids"),next=new JSONArray();if(old!=null)for(int i=0;i<old.length();i++)if(!removed.contains(old.getString(i)))next.put(old.getString(i));j.put("ids",next);WallpaperStore.writeJson(file,j.toString());}}catch(Exception ignored){}}}
 static Result read(Context c){synchronized(STATE_LOCK){try(FileInputStream in=new android.util.AtomicFile(state(c)).openRead()){JSONObject j=new JSONObject(new String(WallpaperStore.readLimited(in,131072),"UTF-8"));List<String> ids=new ArrayList<>(),errors=new ArrayList<>();JSONArray a=j.optJSONArray("ids"),e=j.optJSONArray("errors");if(a!=null)for(int i=0;i<a.length();i++)ids.add(a.getString(i));if(e!=null)for(int i=0;i<e.length();i++)errors.add(e.getString(i));boolean running=j.optBoolean("running")&&busy;if(j.optBoolean("running")&&!busy){JSONArray leases=j.optJSONArray("leases");if(leases!=null)for(int i=0;i<leases.length();i++)try{c.getContentResolver().releasePersistableUriPermission(Uri.parse(leases.getString(i)),Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}errors.add("Importación interrumpida; las fotos guardadas siguen disponibles");}return new Result(j.getString("token"),ids,errors,j.optInt("total"),j.optInt("processed"),running);}catch(Exception ignored){return null;}}}
 private static void notifyResult(Context c){Result result=read(c);new Handler(Looper.getMainLooper()).post(()->{Listener l=listener.get();if(l!=null&&result!=null)l.changed(result);});}
 private static String displayName(Context c,Item item){try(android.database.Cursor cursor=c.getContentResolver().query(item.uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){String name=cursor.getString(0);if(name!=null&&!name.isEmpty())return name;}}catch(Exception ignored){}return item.name;}
 static synchronized boolean start(Context context,List<Item> input){if(busy)return false;final Context c=context.getApplicationContext();final List<Item> items=new ArrayList<>(input.subList(0,Math.min(50,input.size())));if(items.isEmpty())return false;busy=true;final String token=UUID.randomUUID().toString();worker.allowCoreThreadTimeOut(true);worker.execute(()->{List<String> ids=new ArrayList<>(),errors=new ArrayList<>();WallpaperStore store=new WallpaperStore(c);int done=0;try{save(c,token,ids,errors,items,0,true);notifyResult(c);for(Item item:items){File temp=null;try{temp=store.copyUri(item.uri);WallpaperStore.Photo photo=store.importImage(temp,displayName(c,item));ids.add(photo.id);}catch(Exception e){errors.add(item.name+": "+(e instanceof SecurityException?"Android no permite leer esta foto; vuelve a elegirla":e instanceof FileNotFoundException?"Archivo no disponible; vuelve a elegirlo":e.getMessage()==null?"No se pudo importar":e.getMessage()));}finally{if(temp!=null)temp.delete();}done++;save(c,token,ids,errors,items,done,true);notifyResult(c);}}catch(Exception e){errors.add("No se pudo completar la importación");}finally{for(Item item:items)if(item.release)try{c.getContentResolver().releasePersistableUriPermission(item.uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}try{save(c,token,ids,errors,items,done,false);}catch(Exception ignored){}busy=false;notifyResult(c);}});return true;}
}
